  "etudes.steadySixteenthNotes": "일정한 16분음표",
  "etudes.enterAfterAnEighthRest": "8분쉼표 뒤 시작",
  "etudes.restUDU": "쉼 U D U",
  "etudes.beginnerQuarterNotes": "초급 · 4분음표",
  "etudes.intermediateEighthNotes": "중급 · 8분음표",
  "etudes.advancedFourSubdivisionsOnBeat1": "고급 · 첫 박 네 칸",
  "etudes.setTheChordShapeFirst": "코드 모양을 먼저 잡아요",
  "etudes.followTheChordDiagramAboveTheBarAndHoldYourFingersIn": "마디 위 코드표를 먼저 잡고 손가락을 유지합니다. 매 음마다 왼손을 새로 누르며 이동하는 단음 연습과 다릅니다. 과제의 코드표에 표시된 줄만 사용하세요.",
  "etudes.pluckStackedNumbersTogether": "세로 숫자는 동시에 뜯어요",
  "etudes.tabNumbersStackedVerticallyAtTheSameHorizontalPositionSoundTogetherStart": "같은 가로 위치에서 위아래로 겹친 TAB 숫자는 한 번에 울립니다. 베이스와 높은 음의 손가락이 동시에 출발하게 하고, 순서대로 훑어 치지 마세요.",
  "etudes.giveTheThumbAndTrebleFingersSeparateRoles": "엄지와 높은 줄의 역할을 나눠요",
  "etudes.pMeansThumbIIndexMMiddleAndARingFingerStart": "p는 엄지, i는 검지, m은 중지, a는 약지입니다. 엄지는 6·5·4번줄의 베이스, 검지·중지·약지는 3·2·1번줄을 맡는 방식부터 익힙니다. p+m은 엄지와 중지를 동시에 쓴다는 뜻입니다.",
  "etudes.letNotesRingWithinTheSameChord": "같은 코드 안에서는 잔향을 유지해요",
  "etudes.letRingMeansAllowingEarlierNotesToOverlapNaturallyWithTheNext": "let ring은 앞 음이 다음 음과 자연스럽게 겹치도록 울리라는 뜻입니다. 뜯자마자 왼손을 떼거나 다음 손가락으로 울리는 줄을 막지 마세요. 코드가 바뀌면 이전 코드의 불필요한 잔향은 정리합니다.",
  "etudes.distinguishRootAndFifthInTheBass": "루트와 5음의 베이스를 구분해요",
  "etudes.theLowestNoteOnBeat1IsTheRootOfThatBar": "첫 박의 가장 낮은 음은 그 마디 코드의 루트입니다. 교대 베이스 과제에서는 3박에 같은 코드의 5음을 씁니다. 엄지는 박자를 받치고 높은 음은 그 위에 이어지게 들어 보세요.",
  "etudes.muteTogetherAtRests": "쉼표에서는 함께 정리해요",
  "etudes.atRestsInThisIntroductoryScoreLightlyMuteTheRingingStringsAnd": "이 입문 악보의 쉼표에서는 울리던 줄을 가볍게 막고 다음 코드를 준비합니다. 소리를 끊더라도 속으로 박자를 계속 세세요. 코드 전환만 따로 연습해도 좋습니다.",
  "etudes.balanceSimultaneousAndSeparateNotes": "동시음과 분산음의 크기를 맞춰요",
  "etudes.doNotPullHardWhenPluckingSeveralNotesTogetherKeepTheThumb": "여러 음을 함께 뜯을 때 세게 잡아당기지 마세요. 엄지가 높은 음을 덮지 않게 듣고, 코드 소리가 맑게 유지되는 느린 BPM부터 시작합니다. 손의 힘을 빼고 불편하면 쉬세요.",
  "etudes.downAndUpDescribePickDirectionNotPitch": "다운·업은 음높이와 관계없어요",
  "etudes.dDownMovesFromString6TowardString1UUpMoves": "D(다운)는 6번줄에서 1번줄 쪽, U(업)는 반대 방향입니다. 멜로디가 올라간다고 업 피킹을 하는 것은 아닙니다. 일정한 음표를 D–U–D–U로 번갈아 치는 방법을 얼터네이트 피킹이라고 합니다.",
  "etudes.tryStartingWithADownstroke": "처음에는 다운으로 시작해 보세요",
  "etudes.startingContinuousEighthsOrSixteenthsWithADownstrokeGivesPracticeAClear": "연속 8분·16분음표는 다운부터 번갈아 치면 연습 기준이 명확해집니다. 줄이 바뀌어도 매번 다운으로 다시 시작하지 않습니다. 업으로 시작하는 연습도 가능하고, 모든 음악에 하나의 방향만 정답인 것은 아닙니다.",
  "etudes.restsOccupySubdivisionsToo": "쉼표도 박자의 한 칸이에요",
  "etudes.theChartBelowDemonstratesPickingDirectionsAlignedWithSteadySubdivisionsInEighth": "아래 표는 일정한 세부 박에 피킹 방향을 맞추는 연습 예입니다. 8분음표 기준으로 첫 칸을 쉬면 다음 &에서 업으로 들어갑니다. 쉬는 동안 소리는 내지 않고 박을 세세요. 긴 음·쉼표가 섞이면 들리는 음 개수만 세어 무조건 D/U를 정하지 않습니다.",
  "etudes.doNotPickAgainAtHPOrSl": "H·P·SL에서는 다시 치지 않아요",
  "etudes.inThisScoreTheDestinationNotesOfHHammerOnPPull": "이 악보에서 H(해머온)·P(풀오프)·SL(연결 슬라이드)의 도착음은 왼손으로 냅니다. 이어진 묶음의 첫 음을 피킹하고, 줄이 바뀌거나 연결 표시가 끝난 뒤 피킹을 재개합니다. 도착음까지 억지로 다운·업을 넣지 마세요.",
  "etudes.evenLengthAndVolumeBeforeSpeed": "빠르기보다 같은 길이·같은 음량",
  "etudes.keepThePickShallowAgainstTheStringAndUseOnlyTheMovement": "피크를 줄에 깊게 넣지 말고 필요한 만큼만 움직여 보세요. 다운과 업의 소리가 크게 달라지지 않게 듣고, 의도하지 않은 줄은 양손으로 가볍게 뮤트합니다. 코드 반주형은 앞서 뜯은 음을 겹쳐 울리므로 해당 과제 TIP을 따르세요. 어깨와 손의 힘을 풀고 불편하면 멈춰 쉬세요.",
  "etudes.restsAndLongNotesShapeThePhrase": "쉼과 긴 음이 프레이즈를 만들어요",
  "etudes.afterShortNotesHoldLongNotesForTheirWrittenDurationAndStop": "짧은 음을 친 뒤 긴 음은 적힌 길이만큼 유지하고, 쉼표에서는 소리를 끊습니다. 2마디를 질문과 응답처럼 들어 보세요. 모든 음을 세게 치기보다 문장이 시작하고 끝나는 느낌을 살려 보세요.",
  "etudes.practiceDifficultTransitionsSeparately": "어려운 연결만 따로 연습해요",
  "etudes.slowlyRepeatTheTwoToFourNotesAroundAMistakeThenReconnect": "실수가 난 곳의 앞뒤 2~4음을 느리게 반복한 뒤 한 마디, 두 마디, 전체 순서로 연결합니다. 음과 쉼의 길이·뮤트·기법 도착 시점이 안정된 뒤 BPM을 조금씩 올리세요.",
